async function pollPricing(){
  if(!TOKEN||!DATA||pricingBusy||confirming||loading||document.visibilityState!=='visible'||CURRENT==='upi')return;
  pricingBusy=true;const token=TOKEN,epoch=sessionEpoch;
  try{const result=await rpc('getB2BLivePricingV950',[token]);if(TOKEN!==token||epoch!==sessionEpoch||!result?.ok||!Array.isArray(result.products))return;
    let changed=false,up=false,down=false;const before=new Map(products().map(p=>[p.productId,p]));
    const next=result.products.map(fresh=>{const old=before.get(fresh.productId)||{};const oldPrice=Number(old.price),newPrice=Number(fresh.price);if(oldPrice!==newPrice||Number(old.basePrice)!==Number(fresh.basePrice)||old.moq!==fresh.moq||old.qtyStep!==fresh.qtyStep)changed=true;if(old.price!==undefined){up=up||newPrice>oldPrice;down=down||newPrice<oldPrice;}return {...old,...fresh}});
    if(next.length!==products().length)changed=true;if(!changed)return;
    DATA.products=next;renderProducts();renderCart();renderMarket();
    // Keep the chosen schedule and payment method when totals change.
    if(CURRENT==='place')refreshCheckoutView();
    storageSet('nel_b2b_last_prices_v5_'+vendor().vendorId,JSON.stringify(next.map(p=>({productId:p.productId,price:p.price}))));
    msg(up&&down?'Your prices changed. Review your cart.':up?'Prices increased due to market uptrend. Review your cart.':down?'We have a better price for you. Your cart is updated.':'Product pricing details updated.');
  }catch(e){if(TOKEN===token&&epoch===sessionEpoch&&isSessionError(e)){logout(false);msg(e.message)}}finally{pricingBusy=false}
}
