function updateNavigation(id){
  const nav=$('mainNavigation');if(!nav)return;
  nav.classList.toggle('hidden',!TOKEN||!DATA||id==='login'||id==='registration');
  const active=['home','products','cart','orders','account'].includes(id)?id:
    ['place','upi'].includes(id)?'cart':['confirmation','track'].includes(id)?'orders':
    id==='schemes'?'home':'account';
  nav.querySelectorAll('button').forEach(b=>{const selected=b.dataset.page===active;b.classList.toggle('on',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
}
function extraScreen(id,title,body,back='account'){if($(id))return;const s=document.createElement('section');s.id=id;s.className='screen hidden';s.innerHTML='<div class="simpleHead"><button class="back" onclick="show(\''+back+'\')">‹</button><b>'+title+'</b></div><div class="pad">'+body+'</div>';document.querySelector('.phone').append(s)}
function showUpdatePrompt(message='A new app update is ready. Update now?'){
 const panel=$('updatePrompt');if(!panel)return;
 panel.querySelector('p').textContent=message;panel.classList.remove('hidden');
}
function dismissUpdatePrompt(){$('updatePrompt')?.classList.add('hidden')}
function applyAppUpdate(){
 if(confirming){msg('Your order is being submitted. Apply the update after it finishes.');return}
 if(!waitingServiceWorker){dismissUpdatePrompt();return}
 updateActionRequested=true;waitingServiceWorker.postMessage('SKIP_WAITING');
}
function watchAppUpdate(registration){
 const ready=worker=>{if(!worker)return;waitingServiceWorker=worker;if(navigator.serviceWorker.controller)showUpdatePrompt()};
 if(registration.waiting&&navigator.serviceWorker.controller)ready(registration.waiting);
 registration.addEventListener('updatefound',()=>{const installing=registration.installing;if(!installing)return;installing.addEventListener('statechange',()=>{if(installing.state==='installed'&&navigator.serviceWorker.controller)ready(registration.waiting||installing)})});
}
function setup(){
  document.querySelector('.phone').addEventListener('error',e=>{const img=e.target;if(img.tagName!=='IMG'||!img.closest('#plist,#cartList,#bannerTrack')||img.dataset.fallback)return;img.dataset.fallback='1';img.src='../b2c/images/tender-coconut-v2.webp'},true);
  extraScreen('addressEdit','Delivery Address','<div class="field"><label for="addressText">Shop delivery address (same service area)</label><textarea id="addressText" maxlength="500"></textarea></div><button class="wide" onclick="saveAddress()">Save Address</button>','address');extraScreen('history','Transactions','<h3 id="historyTitle"></h3><div id="historyList"></div>','payments');extraScreen('credit','My Credit','', 'payments');extraScreen('legal','Legal & Food Safety','<div id="legalInfo"></div>','account');extraScreen('upi','Pay via UPI','<div class="card"><p id="upiInfo" class="sub"></p><a id="openUpi" class="wide" style="display:block;text-align:center;text-decoration:none" href="#">Open UPI App</a><div class="field" style="margin-top:15px"><label for="utr">UTR / Transaction Number</label><input id="utr" autocomplete="off" maxlength="40"></div><button id="submitUpiBtn" class="wide" onclick="submitUpi()">Submit Payment & Order</button><p class="sub">Submitting a UTR does not mark the payment as paid. Operations verifies it before fulfillment.</p></div>','place');
  document.querySelectorAll('.nav').forEach(n=>n.remove());
  document.querySelector('.phone').insertAdjacentHTML('beforeend','<nav id="mainNavigation" class="nav hidden" aria-label="Main navigation">'+[['home','⌂','Home'],['products','▦','Products'],['cart','🛒','Cart'],['orders','▣','Orders'],['account','♙','Account']].map(([id,icon,label])=>'<button data-page="'+id+'" onclick="show(\''+id+'\')"><span>'+icon+'</span>'+label+(id==='cart'?'<small id="cartCount" class="cartBadge hidden" aria-hidden="true"></small>':'')+'</button>').join('')+'</nav>');
  $('products').querySelector('.pad').insertAdjacentHTML('afterbegin','<div class="mainSummary"><div><small>Available</small><b>—</b></div><div><small>MOQ From</small><b>—</b></div><div><small>Supply</small><b>Live catalogue</b></div></div>');$('products').querySelector('.pad').insertAdjacentHTML('beforeend','<div class="infoPanel"><b>Today’s Supply</b><p>Add the minimum quantity and increase using the product’s step. Availability is checked again at acceptance.</p></div>');
  $('orders').querySelector('.pad').insertAdjacentHTML('afterbegin','<div class="mainSummary"><div><small>Active</small><b>0 Orders</b></div><div><small>Delivered</small><b>0 Orders</b></div><div><small>Total Qty</small><b>0 units</b></div></div>');
  ['home','orders','products'].forEach(id=>$(id).querySelector(id==='home'?'.head':'.simpleHead').insertAdjacentHTML('beforeend','<button class="liveRefresh" aria-label="Refresh account" onclick="refresh()">⟳</button>'));
  $('profilePhone').readOnly=true;$('profilePhone').parentElement.insertAdjacentHTML('afterend','<div class="lockedNote">Registered mobile number. Contact Support if it needs to change.</div>');
  const menu=$('account').querySelector('.menu');menu.insertAdjacentHTML('beforeend','<button id="installBtn" class="hidden" onclick="installApp()"><div><span class="mi">↓</span>Install App</div><span>›</span></button><button onclick="openLegal()"><div><span class="mi">ⓘ</span>Legal & Food Safety</div><span>›</span></button><button onclick="logout()"><div><span class="mi">↪</span>Logout</div><span>›</span></button>');
  $('home').querySelector('.quick button:nth-child(5)').onclick=()=>show('credit');$('payments').querySelector('.menu button:nth-child(2)').onclick=()=>show('credit');$('loginPin').addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()});$('loginPhone').addEventListener('keydown',e=>{if(e.key==='Enter')goPin()});
  document.addEventListener('click',e=>{const b=e.target.closest('button,[data-dot]');if(!b)return;const d=b.dataset;
    if(d.qty)q(decodeURIComponent(d.qty),Number(d.dir));if(d.cartQty)q(decodeURIComponent(d.cartQty),Number(d.dir),true);if(d.add)add(decodeURIComponent(d.add));if(d.remove)removeItem(decodeURIComponent(d.remove));if(d.track)openTrack(decodeURIComponent(d.track));if(d.reorder)reorder(decodeURIComponent(d.reorder));if(d.invoice)invoice(decodeURIComponent(d.invoice));if(d.banner!==undefined)bannerAction(Number(d.banner));if(d.dot!==undefined)setBanner(Number(d.dot));
  });document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.dot!==undefined)setBanner(Number(e.target.dataset.dot))});
  let sx=0;$('bannerViewport').addEventListener('touchstart',e=>sx=e.touches[0].clientX,{passive:true});$('bannerViewport').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>35)setBanner(bi+(dx<0?1:-1))},{passive:true});setInterval(()=>{if(CURRENT==='home'&&document.visibilityState==='visible')setBanner(bi+1)},6000);
}
function openFastHome(data){
 DATA=data;rememberHome(TOKEN,data);workspaceReady=false;cart=parse(storageGet(cartKey()))||{};if(!cart||Array.isArray(cart)||typeof cart!=='object')cart={};
 render();sessionRestoreUi(false);show('home');
}
async function restoreAccount(token){
 const epoch=sessionEpoch;
 try{
  const data=await rpc('getB2BHomeFastV1000',[token]);if(TOKEN!==token||epoch!==sessionEpoch)return;
  if(!data?.vendor?.vendorId||!Array.isArray(data.products))throw Error('Account data could not load. Please retry.');
  openFastHome(data);persistSession();void refresh();
 }catch(e){if(TOKEN!==token||epoch!==sessionEpoch)return;if(isSessionError(e)){logout(false);msg(e.message)}else if(!DATA){showRecovery();msg(e.message)}else{sessionRestoreUi(false);msg('Could not reconnect yet. Your saved Home is available; try refresh when online.')}}
}
async function restoreSession(){const saved=parse(storageGet('nel_b2b_green_session'));let token=storageGet('nel_b2b_token')||storageGet('nel_b2b_token',sessionStorage)||storageGet('nel_b2b_approved_token')||saved?.token;const epoch=sessionEpoch;if(token)sessionRestoreUi(true);
  if(!token)try{const db=await window.NEL_B2B_DB?.get('sessionToken');token=typeof db==='string'?db:db?.token}catch(_){}
  if(epoch!==sessionEpoch||!token)return;TOKEN=token;const savedHome=rememberedHome(token);if(savedHome){openFastHome(savedHome);msg('Showing saved Home while account details refresh.');void restoreAccount(token);return}sessionRestoreUi(true);await restoreAccount(token)
}
async function installApp(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else msg('Open your browser menu and choose Add to Home screen')}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').classList.remove('hidden')});window.addEventListener('appinstalled',()=>$('installBtn').classList.add('hidden'));
window.addEventListener('online',()=>{msg('Connection restored');if(TOKEN)refresh(true)});window.addEventListener('offline',()=>msg('You are offline. Orders require a connection.'));
let lastRefresh=Date.now();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&TOKEN&&Date.now()-lastRefresh>60000){lastRefresh=Date.now();refresh(true)}});
// Keep the current screen active until the customer chooses to update.
if('serviceWorker' in navigator){
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updateActionRequested&&!updateReloaded&&!confirming){updateReloaded=true;location.reload()}});
 navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>{watchAppUpdate(r);r.update();setInterval(()=>r.update(),60000)}).catch(()=>{});
}
setup();restoreSession();
